def _post_trust_dids_verify_document(self, tenant: str) -> None:
    # 跨系统 DID 文档验真：公开错误协议，任何失败都返回
    # 200 + {"valid": false, "reason": "<非空中文原因>"}，成功仅
    # {"valid": true}。请求体须恰含 document（JSON 对象）；非法
    # JSON/非对象/缺失/多余字段均为请求类原因。纯只读，不登记
    # 资源、不写历史或审计，跨租户不可探测。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_invalid("请求体缺失或长度声明非法")
        return
    except Exception:  # noqa: BLE001
        self._send_invalid("请求体读取失败")
        return
    if not raw:
        self._send_invalid("请求体缺失")
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_invalid("请求体不是合法 UTF-8 文本")
        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return

    try:
        valid, reason = store.verify_trust_did_document(tenant, data)
    except Exception:  # noqa: BLE001 验真失败绝不暴露内部细节
        self._send_invalid("验真过程发生内部错误")
        return
    payload: Dict[str, Any] = {"valid": valid}
    if not valid:
        payload["reason"] = reason or "DID 文档验真失败"
    self._send_json(200, payload)

def _post_trust_dids_verify_document_batch(self, tenant: str) -> None:
    # 批量跨系统 DID 文档验真：与单项相同的公开错误协议，任何失败
    # 都返回 HTTP 200。请求体须恰为 {"documents": [文档...]}，
    # 数组非空且不超过 100 项；请求体非法（外层缺失、非法 JSON、
    # 非对象、字段缺失或多余、documents 非数组、空数组或超过上限）
    # 时返回 {"results": [], "reason": "请求..."}。请求级合法时
    # 返回 {"results": [...]}，长度与顺序与输入一致，逐项复用单项
    # 验真规则，失败不短路。纯只读，不登记资源，不写状态、历史或
    # 审计，仅使用当前租户锚点。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体缺失或长度声明非法"},
        )
        return
    except Exception:  # noqa: BLE001
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
        )
        return
    if not raw:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体缺失"}
        )
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_json(
            200,
            {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
        )
        return
    except json.JSONDecodeError:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
        )
        return

    try:
        ok, reason, results = store.verify_trust_did_documents_batch(
            tenant, data
        )
    except Exception:  # noqa: BLE001 验真失败绝不暴露内部细节
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 验真过程发生内部错误"}
        )
        return
    if not ok:
        self._send_json(
            200, {"results": [], "reason": reason or "请求不合法"}
        )
        return
    self._send_json(200, {"results": results})

def _post_trust_dids_deactivate_sync(self, tenant: str) -> None:
    # 外部 DID 停用通告登记。请求/字段非法由 _read_json 与 store
    # 抛 ValidationError -> 400（仅含非空中文 error）；同 did 已
    # 有不同通告由 store 抛 ConflictError -> 409（仅含 error）。
    # 锚点不可用、签名格式错误、验签失败均按公开错误协议返回
    # 200 + {"valid":false,"reason":...}（原因恰为“锚点不可用”/
    # “签名格式错误”/“签名校验失败”）且不写入。首次接受 201，
    # 完全重放 200；成功响应键序 valid、did、key_version、
    # reason、deactivated_at，valid=true。
    data = self._read_json()
    result = store.sync_did_deactivation_notice(tenant, data)
    if not result.get("valid"):
        self._send_invalid(result.get("reason") or "验签失败")
        return
    record = result["record"]
    self._send_json(
        result["status_code"],
        {
            "valid": True,
            "did": record.did,
            "key_version": record.key_version,
            "reason": record.reason,
            "deactivated_at": record.deactivated_at,
        },
    )

def _post_trust_dids_deactivate_sync_batch(self, tenant: str) -> None:
    # 批量外部 DID 停用通告登记：任何失败都返回 HTTP 200。请求体须
    # 恰为 {"items": [项...]}，数组非空且不超过 100 项；请求体非法
    # （外层缺失、非法 JSON、非对象、字段缺失或多余、items 非数组、
    # 空数组或超过上限）时返回 {"results": [], "reason": "请求..."}。
    # 请求级合法时返回 {"results": [...]}，长度与顺序与输入一致，
    # 逐项复用单项登记规则，失败不短路：项结构/字段错误 400、同 did
    # 异通告 409、锚点/签名失败 200、落盘失败 500 均收敛为单项结果
    # （含 http_status 与非空中文 reason），不影响其余项；成功项
    # 首次 201、完全重放 200。显式空 X-Tenant-ID 在此之前由路由
    # 统一判 400。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体缺失或长度声明非法"},
        )
        return
    except Exception:  # noqa: BLE001
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
        )
        return
    if not raw:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体缺失"}
        )
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_json(
            200,
            {"results": [],
             "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
        )
        return
    except json.JSONDecodeError:
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
        )
        return

    try:
        ok, reason, results = (
            store.sync_did_deactivation_notice_batch(tenant, data)
        )
    except Exception:  # noqa: BLE001 批量登记失败绝不暴露内部细节
        self._send_json(
            200, {"results": [], "reason": "请求不合法: 登记过程发生内部错误"}
        )
        return
    if not ok:
        self._send_json(
            200, {"results": [], "reason": reason or "请求不合法"}
        )
        return
    self._send_json(200, {"results": results})

def _post_trust_verify(self, tenant: str) -> None:
    # 与凭证/演示 verify 相同的公开错误协议：任何失败都返回
    # 200 + {"valid": false, "reason": "<非空中文原因>"}。
    # 签名覆盖请求对象去掉 signature 后的规范化 JSON，用匹配
    # (issuer_did, issuer_key_version) 的 active 锚点公钥验签。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_invalid("请求体缺失或长度声明非法")
        return
    except Exception:  # noqa: BLE001
        self._send_invalid("请求体读取失败")
        return
    if not raw:
        self._send_invalid("请求体缺失")
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_invalid("请求体不是合法 UTF-8 文本")
        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return

    try:
        valid, reason = store.verify_trust(tenant, data)
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_invalid("验签过程发生内部错误")
        return
    payload: Dict[str, Any] = {"valid": valid}
    if not valid:
        payload["reason"] = reason or "验签失败"
    self._send_json(200, payload)

def _post_trust_credentials_verify(self, tenant: str) -> None:
    # 跨系统凭证验真：与其他验签端点相同的公开错误协议，任何失败
    # 都返回 200 + {"valid": false, "reason": "<非空中文原因>"}。
    # 请求体须恰含 body（对象）与 signature（非空字符串）；非法
    # JSON/非对象/缺失/多余字段均为请求类原因。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_invalid("请求体缺失或长度声明非法")
        return
    except Exception:  # noqa: BLE001
        self._send_invalid("请求体读取失败")
        return
    if not raw:
        self._send_invalid("请求体缺失")
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_invalid("请求体不是合法 UTF-8 文本")
        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return

    try:
        valid, reason = store.verify_trust_credential(tenant, data)
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_invalid("验签过程发生内部错误")
        return
    payload: Dict[str, Any] = {"valid": valid}
    if not valid:
        payload["reason"] = reason or "验签失败"
    self._send_json(200, payload)

def _post_trust_credentials_verify_synced(
    self, tenant: str
) -> None:
    # POST /v1/trust/credentials/verify-synced：以同步锚点验真
    # 外部凭证（只读）。请求体须恰含 signer_did（非空字符串）、
    # at（非布尔非负整数）、body（JSON 对象）、signature（非空
    # 字符串）；非法 JSON、非对象、键集或类型错误均 400 且仅
    # {"error": 非空中文}。signer_did 未同步或跨租户 404、at
    # 超过同步检查点 409，同形仅 {"error"}。外层合法后任何失败
    # 均 HTTP 200 按键序恰返 {"valid":false,"reason":...}：
    # 凭证字段错误沿用 /v1/trust/credentials/verify 的“凭证”
    # 分类原因；锚点取该来源 cursor<=at 的已同步事件、以
    # (issuer_did, 版本) 最后事件为准，缺失、非 active 或
    # uses 无 vc 均为“同步锚点不可用”；签名须为 ES256、64
    # 字节裸 R||S 无填充 base64url，格式错、验签错、到期依次
    # 为“签名格式错误”“签名校验失败”“凭证已过期”；成功仅
    # {"valid":true}。issuer_key_version 省略按 1 且不注入
    # 正文。纯只读：不改同步页、检查点、锚点、凭证、状态或
    # 审计，重启一致；租户头缺省 default、显式空 400 并隔离。
    data = self._read_json()
    required = ("signer_did", "at", "body", "signature")
    if set(data) != set(required):
        missing = [f for f in required if f not in data]
        if missing:
            raise ValidationError(
                f"请求缺少字段: {', '.join(missing)}"
            )
        extra = sorted(set(data) - set(required))
        raise ValidationError(
            f"请求含多余字段: {', '.join(extra)}"
        )
    signer_did = data["signer_did"]
    if not isinstance(signer_did, str) or not signer_did:
        raise ValidationError(
            "请求不合法: 字段 signer_did 必须为非空字符串"
        )
    at = data["at"]
    if (
        not isinstance(at, int)
        or isinstance(at, bool)
        or at < 0
    ):
        raise ValidationError(
            "请求不合法: 字段 at 必须为非布尔非负整数"
        )
    body = data["body"]
    if not isinstance(body, dict):
        raise ValidationError(
            "请求不合法: 字段 body 必须为 JSON 对象"
        )
    signature = data["signature"]
    if not isinstance(signature, str) or not signature:
        raise ValidationError(
            "请求不合法: 字段 signature 必须为非空字符串"
        )
    try:
        valid, reason = store.verify_trust_credential_synced(
            tenant, signer_did, at, body, signature
        )
    except (NotFoundError, ConflictError):
        raise
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_invalid("验签过程发生内部错误")
        return
    if not valid:
        self._send_invalid(reason or "验签失败")
        return
    self._send_json(200, {"valid": True})

def _post_trust_credentials_verify_synced_with_status(
    self, tenant: str
) -> None:
    # POST /v1/trust/credentials/verify-synced-with-status：以
    # 同步锚点验真外部凭证并合并请求初始本租户状态快照（只读）。
    # 请求体须恰含 signer_did（非空字符串）、at（非布尔非负
    # 整数）、body（JSON 对象）、signature（非空字符串）；空体、
    # 非法 JSON、非对象、键集或类型错误均 400 且仅
    # {"error": 非空中文}。signer_did 未同步或跨租户 404、at
    # 超过同步检查点 409，同形仅 {"error"}。外层合法后任何失败
    # 均 HTTP 200 按键序恰返 {"valid":false,"reason":...}：
    # 凭证字段、锚点、签名覆盖、格式、验签、期限、校验顺序及
    # 原因完全沿用 verify-synced，原验真失败不查状态；验真成功
    # 后以请求初始一次原子读取的本租户状态快照查
    # (issuer_did, credential_id)：未同步、revoked、unknown

def verify_trust_did_document(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str]:
    """跨系统 DID 文档验真（只读），返回 (是否有效, 失败原因)。

    使未在本租户注册 DID 的系统仅凭提交的 DID 文档完成结构、证明与
    信任判断。校验顺序：请求结构 -> 文档字段/结构 -> 锚点 ->
    签名格式 -> 密码学验签。

    - 请求体须恰含 document（JSON 对象）；缺失、多余字段、非法
      JSON/非对象由 HTTP 层与这里统一归为“请求”类原因；
    - document 须恰含 did（非空字符串）、current_key_version（非
      布尔正整数）、verification_methods（数组）、document_proof
      （非空字符串）；方法按 key_version 严格升序且无重复，每项
      恰含 key_version（非布尔正整数）、key_handle（非空字符串）、
      public_key（可解析 P-256 公钥 PEM），文档任何位置不得出现
      私钥；current_key_version 必须等于最高方法版本；
    - 锚点按当前租户 (did, current_key_version) 查找，仅 active 且
      公钥与文档最高版本 public_key 原文完全匹配的锚点可用；
    - document_proof 为 ES256 裸 R||S 无填充 base64url，覆盖除
      document_proof 外整个文档的递归排序紧凑 JSON；
    - 原验真成功后查本租户 (did) 的外部 DID 停用通告：命中返回
      (False, "外部DID已停用：<reason>")，否则维持原验真结果。

    纯只读：不登记资源、不写状态/历史/审计，绝不向上抛异常；跨
    租户各自使用本租户锚点与停用通告，结论随状态文件重启后稳定。
    """
    # 1. 请求结构：恰含 document，且为 JSON 对象
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象"
    if set(data) != {"document"}:
        if "document" not in data:
            return False, "请求缺少字段: document"
        extra = sorted(set(data) - {"document"})
        return False, f"请求含多余字段: {', '.join(extra)}"
    document = data["document"]
    if not isinstance(document, dict):
        return False, "请求不合法: 字段 document 必须为 JSON 对象"

    # 2. 文档顶层字段：恰含四项
    required = (
        "did",
        "current_key_version",
        "verification_methods",
        "document_proof",
    )
    missing = [f for f in required if f not in document]
    if missing:
        return False, f"DID文档缺少字段: {', '.join(missing)}"
    extra = sorted(set(document) - set(required))
    if extra:
        return False, f"DID文档含多余字段: {', '.join(extra)}"

    did = document["did"]
    if not isinstance(did, str) or not did:
        return False, "DID文档字段 did 必须为非空字符串"

    current_version = document["current_key_version"]
    if (
        not isinstance(current_version, int)
        or isinstance(current_version, bool)
        or current_version < 1
    ):
        return False, "DID文档字段 current_key_version 必须为非布尔正整数"

    proof = document["document_proof"]
    if not isinstance(proof, str) or not proof:
        return False, "DID文档字段 document_proof 必须为非空字符串"

    methods = document["verification_methods"]
    if not isinstance(methods, list):
        return False, "DID文档字段 verification_methods 必须为数组"
    if not methods:
        return False, "DID文档 verification_methods 必须为非空数组"

    # 3. 逐个校验验证方法：恰含三字段、类型、P-256 公钥 PEM、无私钥
    method_fields = {"key_version", "key_handle", "public_key"}
    parsed_versions: List[int] = []
    highest_public_pem = ""
    for index, method in enumerate(methods):
        label = f"第 {index + 1} 个验证方法"
        if not isinstance(method, dict):
            return False, f"DID文档{label}必须为 JSON 对象"
        m_missing = [f for f in method_fields if f not in method]
        if m_missing:
            return False, (
                f"DID文档{label}缺少字段: {', '.join(m_missing)}"
            )
        m_extra = sorted(set(method) - method_fields)
        if m_extra:
            return False, (
                f"DID文档{label}含多余字段: {', '.join(m_extra)}"
            )
        version = method["key_version"]
        if (
            not isinstance(version, int)
            or isinstance(version, bool)
            or version < 1
        ):
            return False, (
                f"DID文档{label}的 key_version 必须为非布尔正整数"
            )
        handle = method["key_handle"]
        if not isinstance(handle, str) or not handle:
            return False, (
                f"DID文档{label}的 key_handle 必须为非空字符串"
            )
        public_pem = method["public_key"]
        if not isinstance(public_pem, str) or not public_pem:
            return False, (
                f"DID文档{label}的 public_key 必须为非空字符串 PEM"
            )
        try:
            crypto.validate_public_key_pem(public_pem)
        except (ValueError, TypeError):
            return False, (
                f"DID文档{label}的 public_key 不是合法的 P-256 公钥 PEM"
            )
        parsed_versions.append(version)

    # 文档任何位置都不得携带私钥（PKCS8/PKCS1/SEC1 私钥 PEM 标记）
    try:
        serialized = json.dumps(document, ensure_ascii=False)
    except (TypeError, ValueError):
        return False, "DID文档含无法序列化的内容"
    if "PRIVATE KEY-----" in serialized:
        return False, "DID文档不得包含私钥"

    # 4. 版本须按升序严格递增（无重复）；当前版本须对应最高版本
    if any(
        parsed_versions[i] >= parsed_versions[i + 1]
        for i in range(len(parsed_versions) - 1)
    ):
        return False, (
            "DID文档 verification_methods 必须按 key_version 升序"
            "且不得重复"
        )
    highest_version = parsed_versions[-1]
    if current_version != highest_version:
        return False, (
            "DID文档 current_key_version 必须对应最高密钥版本"
        )
    highest_public_pem = methods[-1]["public_key"]

    # 5. 锚点：当前租户同 DID、同版本、active 且公钥原文完全匹配
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(did)
            if bucket is not None else None
        )
        row = (
            anchors.get(str(current_version))
            if anchors is not None else None
        )
        anchor_public_pem = (
            row.get("public_key", "") if row is not None else ""
        )
        anchor_status = (
            row.get("status", "active") if row is not None else None
        )
        anchor_uses = (
            row.get("uses") if row is not None else None
        )
    if row is None:
        return False, f"锚点不存在: {did}#{current_version}"
    if anchor_status == "revoked":
        return False, f"锚点已吊销: {did}#{current_version}"
    # 用途白名单：active 锚点无 did 用途时按锚点不可用处理
    if anchor_uses is not None and "did" not in anchor_uses:
        return False, f"锚点不存在: {did}#{current_version}"
    if anchor_public_pem != highest_public_pem:
        return False, (
            f"锚点公钥与文档当前版本公钥不匹配: {did}#{current_version}"
        )

    # 6. 签名格式与密码学验签：证明覆盖除 document_proof 外的整个文档
    unsigned = {k: v for k, v in document.items() if k != "document_proof"}
    try:
        crypto.verify(unsigned, proof, anchor_public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，DID 文档或证明可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "签名校验失败: 验签过程发生内部错误"

    # 7. 原验真成功后查本租户外部 DID 停用通告：命中同 did 返回
    #    valid:false 与“外部DID已停用：<reason>”，否则维持原结果。
    notice = self.get_did_deactivation_notice(tenant_id, did)
    if notice is not None:
        return (
            False,
            f"{EXTERNAL_DID_DEACTIVATED_REASON_PREFIX}{notice.reason}",
        )
    return True, ""

