def _anchor_changes_is_well_formed(
    self, changes: Any, after: Any
) -> bool:
    # 变更流结构校验（“变更流非法”）：changes 恰含 GET
    # /v1/trust/anchor-changes 响应的五键，字段协议沿用该入口；
    # events 至多 200 项、cursor 严格递增且均大于外层 after；
    # 非空时 next_after 等于末项 cursor，空时等于 after。
    if not isinstance(changes, dict):
        return False
    if set(changes) != set(_ANCHOR_CHANGES_RESPONSE_KEYS):
        return False
    events = changes["events"]
    if not isinstance(events, list):
        return False
    if len(events) > _ANCHOR_CHANGES_MAX_EVENTS:
        return False
    previous_cursor = after
    for event in events:
        if not isinstance(event, dict):
            return False
        if set(event) != set(_ANCHOR_CHANGE_EVENT_KEYS):
            return False
        cursor = event["cursor"]
        if (
            not isinstance(cursor, int)
            or isinstance(cursor, bool)
            or cursor <= previous_cursor
        ):
            return False
        if event["action"] not in _ANCHOR_CHANGE_ACTIONS:
            return False
        if not isinstance(event["did"], str) or not event["did"]:
            return False
        key_version = event["key_version"]
        if (
            not isinstance(key_version, int)
            or isinstance(key_version, bool)
            or key_version < 1
        ):
            return False
        if (
            not isinstance(event["public_key"], str)
            or not event["public_key"]
        ):
            return False
        if event["status"] not in ("active", "revoked"):
            return False
        uses = event["uses"]
        if not isinstance(uses, list) or not uses:
            return False
        if any(
            not isinstance(use, str) or use not in TRUST_ANCHOR_USES
            for use in uses
        ):
            return False
        if len(set(uses)) != len(uses) or list(uses) != sorted(
            uses, key=TRUST_ANCHOR_USES.index
        ):
            return False
        previous_cursor = cursor
    next_after = changes["next_after"]
    if (
        not isinstance(next_after, int)
        or isinstance(next_after, bool)
        or next_after < 0
    ):
        return False
    expected_next_after = (
        events[-1]["cursor"] if events else after
    )
    if next_after != expected_next_after:
        return False
    signer_did = changes["signer_did"]
    if not isinstance(signer_did, str) or not signer_did:
        return False
    signer_key_version = changes["signer_key_version"]
    if (
        not isinstance(signer_key_version, int)
        or isinstance(signer_key_version, bool)
        or signer_key_version < 1
    ):
        return False
    signature = changes["signature"]
    if not isinstance(signature, str) or not signature:
        return False
    return True

def _verify_anchor_changes_item(
    self, tenant: str, changes: Any, after: int
) -> Optional[str]:
    # 变更流验真：按序返回失败原因（变更流非法 -> 锚点不可用 ->
    # 签名格式错误 -> 签名校验失败），成功返回 None。纯只读，
    # 不依赖本地事件。
    # 阶段一：changes 结构与事件协议
    if not self._anchor_changes_is_well_formed(changes, after):
        return "变更流非法"

    signer_did = changes["signer_did"]
    signer_key_version = changes["signer_key_version"]

    # 阶段二：本租户同 signer_did/版本且含 generic 用途的
    # active 信任锚点
    public_pem = store.get_active_trust_anchor_public_key(
        tenant,
        signer_did,
        signer_key_version,
        required_use="generic",
    )
    if public_pem is None:
        return "锚点不可用"
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return "锚点不可用"

    # 阶段三：签名格式（ES256 裸 R||S 无填充 base64url）
    signature = changes["signature"]
    try:
        crypto.validate_signature_format_strict(signature)
    except crypto.MalformedSignature:
        return "签名格式错误"

    # 阶段四：密码学验签，覆盖 changes 除 signature 外四键的
    # 规范化 JSON
    signed = {
        key: changes[key]
        for key in _ANCHOR_CHANGES_RESPONSE_KEYS[:4]
    }
    try:
        crypto.verify(signed, signature, public_pem)
    except crypto.MalformedSignature:
        return "签名格式错误"
    except crypto.InvalidSignature:
        return "签名校验失败"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露细节
        return "签名校验失败"
    return None

def _read_anchor_changes_request(self) -> Tuple[Dict[str, Any], int]:
    # /v1/trust/anchor-changes/verify 与 /sync 共用的请求体
    # 协议：恰含 changes（JSON 对象）、after（非布尔非负整数），
    # 否则 400 且仅 {"error": 非空中文}。

    # 1. 请求结构：恰含 document，且为 JSON 对象
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象"
    if set(data) != {"document"}:
        if "document" not in data:
            return False, "请求缺少字段: document"
        extra = sorted(set(data) - {"document"})
        return False, f"请求含多余字段: {', '.join(extra)}"
    document = data["document"]
    if not isinstance(document, dict):
        return False, "请求不合法: 字段 document 必须为 JSON 对象"

    # 2. 文档结构：四字段、验证方法、P-256 PEM、禁私钥、升序无重、
    #    当前版本即最高版本。
    did, current_version, highest_public_pem, doc_reason = (
        self._check_did_document_fields(document)
    )
    if doc_reason:
        return False, doc_reason

    # 3. 锚点：当前租户同 DID、同版本、active 且公钥原文完全匹配
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(did)
            if bucket is not None else None
        )
        row = (
            anchors.get(str(current_version))
            if anchors is not None else None
        )
        anchor_public_pem = (
            row.get("public_key", "") if row is not None else ""
        )
        anchor_status = (
            row.get("status", "active") if row is not None else None
        )
        anchor_uses = (
            row.get("uses") if row is not None else None
        )
    if row is None:
        return False, f"锚点不存在: {did}#{current_version}"
    if anchor_status == "revoked":
        return False, f"锚点已吊销: {did}#{current_version}"
    # 用途白名单：active 锚点无 did 用途时按锚点不可用处理
    if anchor_uses is not None and "did" not in anchor_uses:
        return False, f"锚点不存在: {did}#{current_version}"
    if anchor_public_pem != highest_public_pem:
        return False, (
            f"锚点公钥与文档当前版本公钥不匹配: {did}#{current_version}"
        )

    # 6. 签名格式与密码学验签：证明覆盖除 document_proof 外的整个文档
    proof = document["document_proof"]
    unsigned = {k: v for k, v in document.items() if k != "document_proof"}
    try:
        crypto.verify(unsigned, proof, anchor_public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，DID 文档或证明可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "签名校验失败: 验签过程发生内部错误"

    # 7. 原验真成功后查本租户外部 DID 停用通告：命中同 did 返回
    #    valid:false 与“外部DID已停用：<reason>”，否则维持原结果。
    notice = self.get_did_deactivation_notice(tenant_id, did)
    if notice is not None:
        return (
            False,
            f"{EXTERNAL_DID_DEACTIVATED_REASON_PREFIX}{notice.reason}",
        )
    return True, ""

